"css": "\n.twofold-desk { border-top-color: var(--c9b80cf3-a154-4d43-86f1-c03a7e162ace); }\n.twofold-desk.is-personal { border-top-color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }\n.twofold-desk-tel { position: relative; color: var(--4eb6c52a-bd37-4578-a239-77714376d382); text-decoration: none; transition: transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-desk.is-personal .twofold-desk-tel { color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }\nhtml[data-audience=\"business\"] :scope .twofold-desk.is-personal { border-top-color: var(--c9b80cf3-a154-4d43-86f1-c03a7e162ace); }\nhtml[data-audience=\"business\"] :scope .twofold-desk.is-personal .twofold-desk-tel { color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }\nhtml[data-audience=\"business\"] :scope .twofold-desk.is-business { border-top-color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }\nhtml[data-audience=\"business\"] :scope .twofold-desk.is-business .twofold-desk-tel { color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }\n.twofold-desk-tel::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: -0.08em; height: 2px; background-color: currentColor; opacity: 0; transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-desk-tel:hover::after { opacity: 1; }\n.twofold-desk-tel:active { transform: translateY(1px); }\n.twofold-desk-tel:focus-visible { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); outline-offset: 4px; border-radius: 2px; }\n.twofold-fill { padding: 0 0.25em; border: 1px dashed color-mix(in oklab, var(--543912ec-00bd-40f1-a5ea-edcaab7caea5) 70%, transparent); border-radius: 3px; color: var(--543912ec-00bd-40f1-a5ea-edcaab7caea5); }\n.twofold-credits a { color: var(--326cc48f-754c-468c-afb8-7812bcfa2b4d); text-decoration-line: underline; text-underline-offset: 0.2em; transition: color 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-credits a:hover { color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }\n.twofold-where a { color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }\n@media (prefers-reduced-motion: reduce) { .twofold-desk-tel, .twofold-desk-tel::after, .twofold-credits a { transition: none; } }\n"
